//! Frozen direct-policy qualification with fresh reset seeds and headings.
#![cfg(feature = "robots")]
#[path = "../examples/robots/learning/mod.rs"]
mod learning;
#[path = "../runs/quality-research/tracking-teacher-controller.rs"]
mod teacher;
use bevy::math::Vec3;
use bevy_gym::{Env,robots::{DroneHover,DroneObservation},training::RecurrentPpoPolicy};
fn features(obs: DroneObservation) -> [f32; 13] {
 let mut input = [0.0; 13];
 input[..12].copy_from_slice(&learning::encode(obs));
 let forward = obs.orientation() * Vec3::NEG_Z;
 input[12] = forward.cross(Vec3::NEG_Z).y.atan2(forward.dot(Vec3::NEG_Z)) / std::f32::consts::PI;
 input
}
#[test]
fn qualify_frozen_heading() {
 let selected:serde_json::Value=serde_json::from_slice(&std::fs::read("runs/quality-research/heading-markov-imitation/selected.json").unwrap()).unwrap();
 let mut config=learning::learning_config();config.actor_hidden_size=64;config.actor_learning_rate=0.001;
 let policy=RecurrentPpoPolicy::load_bytes(std::fs::read(selected["checkpoint"].as_str().unwrap()).unwrap(),13,13,1,&[0.0;4],&[1.0;4],&config).unwrap();
 let hover=learning::load_policy(include_bytes!("../assets/robots/recovery.mpk").to_vec()).unwrap();
 let mut rows=Vec::new();
 for (name,desired) in [("north",Vec3::NEG_Z),("east",Vec3::X),("south",Vec3::Z),("west",Vec3::NEG_X)] {
  for offset in 1001..=1032 {
   let seed=u64::MAX-offset;
   for controller in ["learned","teacher","hover"] {
    let mut env=DroneHover::disturbed();let mut obs=env.reset(Some(seed)).observation;
    let memory=policy.initial_memory();let mut hover_memory=hover.initial_memory();let mut reward=0.0;let mut steps=0;let mut settled=0;let mut ended=false;let mut trace=Vec::new();
    for _ in 0..500 {
     let mut input=features(obs);let forward=obs.orientation()*Vec3::NEG_Z;
     input[12]=forward.cross(desired).y.atan2(forward.dot(desired))/std::f32::consts::PI;
     let action=match controller {
      "learned"=>{let p=policy.mean_action(&input,&memory).unwrap();learning::decode_action(&p.action).unwrap()},
      "teacher"=>teacher::teacher(obs,Vec3::new(0.0,2.0,0.0),desired),
      _=>{let p=hover.mean_action(&learning::encode(obs),&hover_memory).unwrap();hover_memory=p.next_memory;learning::decode_action(&p.action).unwrap()}
     };
     let result=env.step(action);obs=result.observation;steps+=1;ended=result.is_done();
     let forward=obs.orientation()*Vec3::NEG_Z;let up=obs.orientation()*Vec3::Y;
     let distance=obs.position().distance(Vec3::new(0.0,2.0,0.0));
     let error=forward.cross(desired).y.atan2(forward.dot(desired));
     if !ended {reward+=f64::from((up.y+1.0)/2.0/(1.0+distance*distance))*f64::from(0.25+0.75*(forward.dot(desired)+1.0)/2.0);}
     if error.abs()<std::f32::consts::PI/12.0 && distance<0.5 {settled+=1;}else{settled=0;}
     if offset==1001 && steps%10==0 {trace.push(serde_json::json!({"time":steps as f32*0.02,"position":obs.position().to_array(),"orientation":obs.orientation().to_array(),"yaw_error_radians":error,"motors":action.fractions()}));}
     if ended {break;}
    }
    let f=obs.orientation()*Vec3::NEG_Z;
    rows.push(serde_json::json!({"seed":seed,"heading":name,"controller":controller,"steps":steps,"ended":ended,"reward":reward,"settled":settled,"distance":obs.position().distance(Vec3::new(0.0,2.0,0.0)),"yaw_error_radians":f.cross(desired).y.atan2(f.dot(desired)),"trace":trace}));
   }
  }
 }
 std::fs::write("runs/quality-research/heading-markov-imitation/held-out.json",serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
 let learned:Vec<_>=rows.iter().filter(|row|row["controller"]=="learned").collect();
 assert_eq!(learned.len(),128);
 assert!(learned.iter().all(|row| !row["ended"].as_bool().unwrap() && row["steps"]==500 && row["distance"].as_f64().unwrap()<=0.5 && row["settled"].as_u64().unwrap()>=100 && row["reward"].as_f64().unwrap()>=400.0));

}

