#[test]
fn qualify_frozen_heading() {
 let selected:serde_json::Value=serde_json::from_slice(&std::fs::read("runs/quality-research/heading-imitation-damped/selected.json").unwrap()).unwrap();
 let mut config=learning::learning_config();config.actor_hidden_size=16;config.critic_hidden_sizes=vec![32,32];config.initial_log_std=-1.0;config.actor_learning_rate=0.001;
 let policy=RecurrentPpoPolicy::load_bytes(std::fs::read(selected["checkpoint"].as_str().unwrap()).unwrap(),13,13,1,&[-0.15],&[0.15],&config).unwrap();
 let mut rows=Vec::new();
 for (name,desired) in [("north",Vec3::NEG_Z),("east",Vec3::X),("south",Vec3::Z),("west",Vec3::NEG_X)] {
  for offset in 1..=32 {
   let seed=u64::MAX-offset;
   for controller in ["learned","teacher","hover"] {
    let mut env=TurnTask::new();let mut obs=env.reset(Some(seed)).observation;
    let mut memory=policy.initial_memory();let mut reward=0.0;let mut steps=0;let mut settled=0;let mut ended=false;let mut trace=Vec::new();
    for _ in 0..500 {
     let mut input=features(obs);let forward=obs.orientation()*Vec3::NEG_Z;
     input[12]=forward.cross(desired).y.atan2(forward.dot(desired))/std::f32::consts::PI;
     let trim=match controller {
      "learned"=>{let p=policy.mean_action(&input,&memory).unwrap();memory=p.next_memory;decode_action(&p.action).unwrap()},
      "teacher"=>(0.2*std::f32::consts::PI*input[12]-0.2*obs.angular_velocity().y).clamp(-0.15,0.15),
      _=>0.0
     };
     let result=env.step(trim);obs=result.observation;steps+=1;ended=result.is_done();
     let forward=obs.orientation()*Vec3::NEG_Z;let up=obs.orientation()*Vec3::Y;
     let distance=obs.position().distance(Vec3::new(0.0,2.0,0.0));
     let error=forward.cross(desired).y.atan2(forward.dot(desired));
     if !ended {reward+=f64::from((up.y+1.0)/2.0/(1.0+distance*distance))*f64::from(0.25+0.75*(forward.dot(desired)+1.0)/2.0);}
     if error.abs()<std::f32::consts::PI/12.0 && distance<0.5 {settled+=1;}else{settled=0;}
     if offset==1 && steps%10==0 {trace.push(serde_json::json!({"time":steps as f32*0.02,"position":obs.position().to_array(),"orientation":obs.orientation().to_array(),"yaw_error_radians":error,"trim":trim}));}
     if ended {break;}
    }
    let f=obs.orientation()*Vec3::NEG_Z;
    rows.push(serde_json::json!({"seed":seed,"heading":name,"controller":controller,"steps":steps,"ended":ended,"reward":reward,"settled":settled,"distance":obs.position().distance(Vec3::new(0.0,2.0,0.0)),"yaw_error_radians":f.cross(desired).y.atan2(f.dot(desired)),"trace":trace}));
   }
  }
 }
 std::fs::write("runs/quality-research/heading-imitation-damped/held-out.json",serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
}

