//! Experimental position and attitude teacher using the unchanged physical task.
#![cfg(feature = "robots")]
use bevy::math::{Mat3,Quat,Vec3};
use bevy_gym::{Env,robots::{DroneHover,DroneObservation,DroneAction}};
fn teacher(obs:DroneObservation,target:Vec3,heading:Vec3)->DroneAction {
 let error=target-obs.position();
 let mut acc=error*3.0-obs.linear_velocity()*3.0+Vec3::Y*9.81;
 acc.y=acc.y.clamp(4.905,14.715);
 let horizontal=Vec3::new(acc.x,0.0,acc.z).clamp_length_max(4.0);acc.x=horizontal.x;acc.z=horizontal.z;
 let up=acc.normalize();let forward=(heading-up*heading.dot(up)).normalize();let right=forward.cross(up);
 let desired=Quat::from_mat3(&Mat3::from_cols(right,up,-forward));
