//! Learn direct four-motor heading control from a bounded physical reference.
#![cfg(feature = "robots")]
#[path = "../examples/robots/learning/mod.rs"]
mod learning;
#[path = "../runs/quality-research/tracking-teacher-controller.rs"]
mod teacher;
use bevy::math::Vec3;
use bevy_gym::{Env,robots::{DroneHover,DroneObservation},training::{RecurrentPpoAgent,RecurrentPpoPolicy,RecurrentBehaviorMemorySample,SeedConfig}};
fn features(obs: DroneObservation) -> [f32; 13] {
 let mut input = [0.0; 13];
 input[..12].copy_from_slice(&learning::encode(obs));
 let forward = obs.orientation() * Vec3::NEG_Z;
 input[12] = forward.cross(Vec3::NEG_Z).y.atan2(forward.dot(Vec3::NEG_Z)) / std::f32::consts::PI;
 input
}

fn evaluate(policy:&RecurrentPpoPolicy)->serde_json::Value {
 let mut rows=Vec::new();
 for seed in [0,1,2,42,u64::MAX] {
  let mut env=DroneHover::disturbed();let mut obs=env.reset(Some(seed)).observation;let mut memory=policy.initial_memory();
  let mut reward=0.0;let mut steps=0;let mut settled=0;let mut ended=false;
  for _ in 0..500 {
   let p=policy.mean_action(&features(obs),&memory).unwrap();memory=p.next_memory;
   let result=env.step(learning::decode_action(&p.action).unwrap());obs=result.observation;steps+=1;ended=result.is_done();
   let forward=obs.orientation()*Vec3::NEG_Z;
   reward+=result.reward*f64::from(0.25+0.75*(1.0-forward.z)/2.0);
   if features(obs)[12].abs()<0.083333336 && obs.position().distance(Vec3::new(0.0,2.0,0.0))<0.5 {settled+=1;}else{settled=0;}
   if ended {break;}
  }
  rows.push(serde_json::json!({"seed":seed,"steps":steps,"ended":ended,"reward":reward,"settled":settled,"distance":obs.position().distance(Vec3::new(0.0,2.0,0.0)),"yaw_error":features(obs)[12]}));
 }
 serde_json::json!(rows)
}
#[test]
fn teach_heading() {
 let seeds=SeedConfig::from_root(7);let mut config=learning::learning_config();config.actor_learning_rate=0.001;
 let mut agent=RecurrentPpoAgent::load_actor_with_inserted_input_feature_and_fresh_critic("assets/robots/recovery.mpk",12,12,13,1,&[0.0;4],&[1.0;4],config,seeds).unwrap();
 let mut envs:Vec<_>=(0..8).map(|lane|{let mut env=DroneHover::disturbed();env.reset(Some((seeds.environment_episode(lane,0)&(u64::MAX>>1))|(1<<10)));env}).collect();
 let mut memories=vec![agent.policy().initial_memory();8];let mut steps=[0usize;8];let mut episodes=[0u64;8];
 std::fs::create_dir_all("runs/quality-research/heading-direct-imitation").unwrap();
 for update in 1..=600 {
  let policy=agent.policy();let mut samples=Vec::with_capacity(512);
  for lane in 0..8 {
   for _ in 0..64 {
    let obs=envs[lane].observation();let input=features(obs);let target=teacher::teacher(obs,Vec3::new(0.0,2.0,0.0),Vec3::NEG_Z);
    let p=policy.mean_action(&input,&memories[lane]).unwrap();
    samples.push(RecurrentBehaviorMemorySample{observation:input.to_vec(),action:target.fractions().to_vec(),initial_memory:memories[lane].clone()});
    memories[lane]=p.next_memory;
    let action=if update<=100 {target}else{learning::decode_action(&p.action).unwrap()};
    let result=envs[lane].step(action);steps[lane]+=1;
    if result.is_done() || steps[lane]==500 {
     episodes[lane]+=1;steps[lane]=0;memories[lane]=policy.initial_memory();
     envs[lane].reset(Some((seeds.environment_episode(lane,episodes[lane])&(u64::MAX>>1))|(1<<10)));
    }
   }
  }
  let mut loss=0.0;for _ in 0..10 {loss=agent.behavior_clone_with_memory(&samples).unwrap();}
  if update==1 || update%20==0 {
   let policy=agent.policy();let scores=evaluate(&policy);println!("{update} loss={loss}: {scores}");
   std::fs::write(format!("runs/quality-research/heading-direct-imitation/{update}.json"),scores.to_string()).unwrap();
   std::fs::write(format!("runs/quality-research/heading-direct-imitation/{update}.mpk"),policy.to_bytes().unwrap()).unwrap();
  }
 }
}
